settings.liquid:
{% assign badges = product.metafields.custom.badges.value %}
{% assign _lc = localization.language.iso_code | default: shop.locale | default: 'EN' | upcase %}

{% if badges != blank %}
  <div class="cj-custom-badge-list">
    {% for badge in badges %}
      {% assign badge_raw = badge | strip %}
      {% assign badge_key = badge_raw | upcase %}

      {% case badge_key %}
        {% when 'NEW' %}
          {% case _lc %}
            {% when 'NL' %}
              {% assign badge_text = 'NIEUW' %}
            {% when 'DE' %}
              {% assign badge_text = 'NEU' %}
            {% else %}
              {% assign badge_text = 'NEW' %}
          {% endcase %}
        {% else %}
          {% assign badge_text = badge_raw %}
      {% endcase %}

      <span class="cj-custom-badge">
        {{ badge_text }}
      </span>
    {% endfor %}
  </div>
{% endif %}

<style>
  /* Hide native Impact badge placement on PDP */
  .product-info__badge-list {
    display: none !important;
  }

  .cj-custom-badge-list {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 0 0 12px;
  }

  .cj-custom-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 24px;
    padding: 0 9px;
    border-radius: 999px;
    background: #111;
    color: #fff;
    font-family: inherit;
    font-size: 10px;
    line-height: 1;
    font-weight: 400;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  @media (max-width: 768px) {
    .cj-custom-badge-list {
      margin: 0px 0 10px;
    }

    .cj-custom-badge {
      min-height: 22px;
      padding: 0 8px;
      font-size: 10px;
    }
  }
</style>

{% liquid
  assign pack_1_price = product.price | times: 0.78
  assign pack_1_compare = product.price
  assign pack_1_save = pack_1_compare | minus: pack_1_price

  assign pack_2_compare = product.price | times: 2
  assign pack_2_each = product.price | times: 0.66
  assign pack_2_total = pack_2_each | times: 2
  assign pack_2_save = pack_2_compare | minus: pack_2_total
%}

<div class="curv-pack-selector" data-curv-pack-selector>
  <script type="application/json" data-curv-product-json>
    {{ product | json }}
  </script>

  <p class="curv-pack-selector__title">
    Choose your savings: <strong data-pack-title>2-pack</strong>
  </p>

  <div class="curv-pack-selector__cards">
    <button type="button" class="curv-pack-selector__card" data-pack="1">
      <span class="curv-pack-selector__name">1 unit</span>
      <span class="curv-pack-selector__save curv-pack-selector__save--light">
        Save {{ pack_1_save | money_without_trailing_zeros }}
      </span>
      <s>{{ pack_1_compare | money }}</s>
      <strong>{{ pack_1_price | money }}</strong>
    </button>

    <button type="button" class="curv-pack-selector__card is-selected" data-pack="2">
      <span class="curv-pack-selector__badge">MOST POPULAR</span>
      <span class="curv-pack-selector__name">2-pack</span>
      <span class="curv-pack-selector__save">
        Save {{ pack_2_save | money_without_trailing_zeros }}
      </span>
      <s>{{ pack_2_compare | money }}</s>
      <strong>{{ pack_2_each | money }}<small>/each</small></strong>
    </button>
  </div>

  <div class="curv-pack-selector__colors">
    <p class="curv-pack-selector__color-title">
      Color: <strong data-color-summary></strong>
    </p>

    <div data-color-rows></div>
  </div>
</div>

<style>
.curv-pack-selector {
  margin: 18px 0;
  font-size: 14px;
}

.curv-pack-selector__title {
  margin: 0 0 12px;
  font-size: 15px;
}

.curv-pack-selector__cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.curv-pack-selector__card {
  position: relative;
  min-height: 128px;
  border: 1px solid #cfcfcf;
  border-radius: 7px;
  background: #fff;
  padding: 20px 10px 16px;
  text-align: center;
  cursor: pointer;
}

.curv-pack-selector__card.is-selected {
  background: #f5faf9;
  border-color: #b7cdb8;
  box-shadow: inset 0 0 0 1px #b7cdb8;
}

.curv-pack-selector__badge {
  position: absolute;
  top: -11px;
  left: 50%;
  transform: translateX(-50%);
  background: #efc23a;
  color: #111;
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

.curv-pack-selector__name {
  display: block;
  font-weight: 800;
  margin-bottom: 7px;
}

.curv-pack-selector__save {
  display: inline-block;
  background: #c93f3b;
  color: #fff;
  padding: 3px 7px;
  border-radius: 3px;
  font-weight: 800;
  font-size: 13px;
  margin-bottom: 5px;
}

.curv-pack-selector__save--light {
  background: #f1f1f1;
  color: #111;
  border: 1px solid #ccc;
}

.curv-pack-selector__card s {
  display: block;
  color: #555;
  font-size: 13px;
  margin-bottom: 2px;
}

.curv-pack-selector__card strong {
  display: block;
  font-size: 18px;
  font-weight: 900;
}

.curv-pack-selector__card small {
  font-size: 12px;
  font-weight: 400;
  margin-left: 2px;
}

.curv-pack-selector__colors {
  margin-top: 22px;
}

.curv-pack-selector__color-title {
  margin: 0;
  padding-bottom: 10px;
  border-bottom: 1px solid #ddd;
}

.curv-pack-selector__row {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 14px;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid #ddd;
}

.curv-pack-selector__thumb {
  width: 58px;
  height: 72px;
  object-fit: cover;
}

.curv-pack-selector__row-label {
  margin: 0 0 9px;
}

.curv-pack-selector__swatches {
  display: flex;
  gap: 13px;
  align-items: center;
}

.curv-pack-selector__swatch {
  width: 29px;
  height: 29px;
  border-radius: 50%;
  border: 1px solid #cfcfcf;
  cursor: pointer;
  background-size: cover;
  background-position: center;
}

.curv-pack-selector__swatch.is-selected {
  outline: 2px solid #111;
  outline-offset: 3px;
}

@media(max-width: 480px) {
  .curv-pack-selector__card {
    min-height: 120px;
    padding-left: 8px;
    padding-right: 8px;
  }

  .curv-pack-selector__card strong {
    font-size: 17px;
  }
}

.curv-pack-selector__card {
  pointer-events: auto;
  z-index: 1;
}

.curv-pack-selector__swatch {
  appearance: none;
  -webkit-appearance: none;
  padding: 0;
}
.curv-pack-selector__card,
.curv-pack-selector__swatch {
  pointer-events: auto;
}

.curv-pack-selector__swatch {
  appearance: none;
  -webkit-appearance: none;
  padding: 0;
}
</style>

<script>
(function () {
  function initCurvPackSelector() {
    const root = document.querySelector('[data-curv-pack-selector]');
    if (!root || root.dataset.initialized === 'true') return;
    root.dataset.initialized = 'true';

    const jsonEl = root.querySelector('[data-curv-product-json]');
    const form = document.querySelector('form[action*="/cart/add"]') || document.querySelector('product-form form');
    if (!jsonEl || !form) return;

    const product = JSON.parse(jsonEl.textContent);

    const colors = [...new Set(product.variants.map(v => v.option1).filter(Boolean))];
    const sizes = [...new Set(product.variants.map(v => v.option2).filter(Boolean))];

    let selectedPack = 2;
    let selectedColors = [colors[0], colors[0]];

    const colorHex = {
      Black: '#000000',
      White: '#ffffff',
      Cocoa: '#8b563d',
      Sand: '#e7d4b6',
      Red: '#d83a32',
      Pink: '#e86aa0'
    };

    function getCurrentSize() {
      const checked = document.querySelector('[data-option-position="2"]:checked');
      if (checked) {
        const label = document.querySelector('label[for="' + checked.id + '"]');
        if (label) return label.textContent.trim();
      }

      const variantInput = form.querySelector('[name="id"]');
      const variant = variantInput
        ? product.variants.find(v => String(v.id) === String(variantInput.value))
        : null;

      return variant?.option2 || sizes[0];
    }

    function findVariant(color, size) {
      return product.variants.find(v =>
        String(v.option1) === String(color) &&
        String(v.option2) === String(size) &&
        v.available
      );
    }

    function getColorImage(color) {
      const variant = product.variants.find(v =>
        String(v.option1) === String(color) &&
        v.featured_image &&
        v.featured_image.src
      );

      return variant?.featured_image?.src || product.featured_image || '';
    }

    function updateSummary() {
      root.querySelector('[data-color-summary]').textContent =
        selectedPack === 1 ? selectedColors[0] : selectedColors.slice(0, 2).join(', ');

      root.querySelector('[data-pack-title]').textContent =
        selectedPack === 1 ? '1 unit' : '2-pack';
    }

    function renderRows() {
      const container = root.querySelector('[data-color-rows]');
      if (!container) return;

      container.innerHTML = '';

      const count = selectedPack === 1 ? 1 : 2;

      for (let i = 0; i < count; i++) {
        if (!selectedColors[i]) selectedColors[i] = colors[0];

        const row = document.createElement('div');
        row.className = 'curv-pack-selector__row';

        const img = document.createElement('img');
        img.className = 'curv-pack-selector__thumb';
        img.src = getColorImage(selectedColors[i]);
        img.alt = selectedColors[i];

        const content = document.createElement('div');

        const label = document.createElement('p');
        label.className = 'curv-pack-selector__row-label';
        label.innerHTML = 'Color: <strong>' + selectedColors[i] + '</strong>';

        const swatches = document.createElement('div');
        swatches.className = 'curv-pack-selector__swatches';

        colors.forEach(color => {
          const swatch = document.createElement('button');
          swatch.type = 'button';
          swatch.className = 'curv-pack-selector__swatch';
          swatch.style.backgroundColor = colorHex[color] || '#ddd';
          swatch.setAttribute('aria-label', color);

          if (color === selectedColors[i]) swatch.classList.add('is-selected');

          swatch.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            selectedColors[i] = color;
            renderRows();
            updateSummary();
          });

          swatches.appendChild(swatch);
        });

        content.appendChild(label);
        content.appendChild(swatches);

        row.appendChild(img);
        row.appendChild(content);
        container.appendChild(row);
      }

      updateSummary();
    }

    root.querySelectorAll('[data-pack]').forEach(card => {
      card.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();

        selectedPack = Number(card.dataset.pack);

        root.querySelectorAll('[data-pack]').forEach(el => {
          el.classList.toggle('is-selected', el === card);
        });

        renderRows();
      });
    });

    document.addEventListener('change', function (e) {
      if (e.target && e.target.matches('[data-option-position="2"]')) {
        setTimeout(renderRows, 50);
      }
    });

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      e.stopImmediatePropagation();

      const size = getCurrentSize();
      const count = selectedPack === 1 ? 1 : 2;
      const items = [];

      for (let i = 0; i < count; i++) {
        const variant = findVariant(selectedColors[i], size);

        if (!variant) {
          alert(selectedColors[i] + ' / ' + size + ' is unavailable.');
          return;
        }

        items.push({
          id: variant.id,
          quantity: 1
        });
      }

      fetch('/cart/add.js', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify({ items: items })
      })
      .then(res => {
        if (!res.ok) throw new Error('Add to cart failed');
        return res.json();
      })
      .then(() => fetch('/cart.js'))
      .then(res => res.json())
      .then(cart => {
        document.documentElement.dispatchEvent(new CustomEvent('cart:refresh', { bubbles: true, detail: { cart } }));
        document.documentElement.dispatchEvent(new CustomEvent('cart:change', { bubbles: true, detail: { cart } }));
        document.documentElement.dispatchEvent(new CustomEvent('cart-drawer:open', { bubbles: true }));
        document.documentElement.dispatchEvent(new CustomEvent('cart:open', { bubbles: true }));

        const cartDrawer =
          document.querySelector('cart-drawer') ||
          document.querySelector('#cart-drawer') ||
          document.querySelector('[data-cart-drawer]');

        if (cartDrawer && typeof cartDrawer.open === 'function') {
          cartDrawer.open();
        }
      })
      .catch(err => {
        console.error('CURV pack selector error:', err);
        alert('Could not add to cart. Please try again.');
      });
    }, true);

    renderRows();
  }

  document.addEventListener('DOMContentLoaded', initCurvPackSelector);
  document.addEventListener('shopify:section:load', initCurvPackSelector);
})();
</script>
